#ifndef FPGA_REGS_H
#define FPGA_REGS_H

#define FPGA_REG_ID              0x00u  /* RO   0x47344650 ("G4FP") */
#define FPGA_REG_VERSION         0x01u  /* RO   5 */
#define FPGA_REG_SCRATCH         0x02u  /* RW   Link test register */
#define FPGA_REG_LEDS            0x03u  /* RW   [13:0] user LEDs, lit only while armed. LED15 = armed and LED14 = fault are driven by the safety layer */
#define FPGA_REG_SWITCHES        0x04u  /* RO   [15:0] switches, [20:16] buttons U, L, R, D, C (debounced) */
#define FPGA_REG_SEG7            0x05u  /* RW   [15:0] hex digits, [19:16] digit enables, [20] use register (else frame count) */
#define FPGA_REG_TICK_DIV        0x06u  /* RW   LOOP_TICK period in 100 MHz clocks; 0 = off; 100000 = 1 kHz. Writes ignored while armed */
#define FPGA_REG_TICK_COUNT      0x07u  /* RO   Ticks since reset */
#define FPGA_REG_IRQ_STATUS      0x08u  /* RW1C [0] tick, [1] switch/button change, [2] CRC error, [3] fault latched (any cause) */
#define FPGA_REG_IRQ_ENABLE      0x09u  /* RW   Same bits; FPGA_IRQ = any enabled status bit */
#define FPGA_REG_FRAMES_OK       0x0Au  /* RO   Good frames */
#define FPGA_REG_CRC_ERRS        0x0Bu  /* RO   Rejected frames */
#define FPGA_REG_TIME_US         0x0Cu  /* RO   Free-running microsecond timestamp */
#define FPGA_REG_CTRL            0x0Du  /* W    [0] clear FRAMES_OK, CRC_ERRS, TICK_COUNT and ENC_ERRS */
#define FPGA_REG_SCRATCH_RAM     0x10u  /* RW   16 free words (burst self-test) */
#define FPGA_SCRATCH_RAM_WORDS   16u
#define FPGA_REG_ARM             0x20u  /* RW   Write ARM_KEY (0x41524D21) to arm: needs SW15 up, no fault, tick running. Any other value disarms. Read: [0] armed, [1] SW15, [2] fault, [3] tick running */
#define FPGA_REG_WDT_TICKS       0x21u  /* RW   [7:0] watchdog limit in loop ticks (1-255, 0 is stored as 1). A tick that finds this many ticks since the last kick latches FAULT.WDT. Writes ignored while armed */
#define FPGA_REG_FAULT_STATUS    0x22u  /* RO   Latched causes: [0] WDT missed kicks, [1] LINK 4 rejected frames in a row, [2] ESTOP btnD, [3] ARM_LOST SW15 down while armed. Any fault disarms and holds FAULT_N low */
#define FPGA_REG_FAULT_CLEAR     0x23u  /* W    Write 1s to clear FAULT_STATUS bits. ESTOP stays set while btnD is held */
#define FPGA_REG_WDT_KICK        0x24u  /* RW   Any write feeds the watchdog. Read: [7:0] ticks since the last kick (0 while disarmed) */
#define FPGA_REG_M1_DUTY         0x25u  /* RW   [15:0] signed duty, +/-32767 = +/-100 % (-32768 acts as -32767): positive PWMs IN1, negative IN2, 0 = coast. Clamped to +/-DUTY_LIMIT. Reads sign-extended. Held at 0 while disarmed (writes ignored), so arming never starts a motor */
#define FPGA_REG_M2_DUTY         0x26u  /* RW   Same for motor 2 */
#define FPGA_REG_DUTY_LIMIT      0x27u  /* RW   [14:0] largest |duty| applied to either motor; reset 16384 = 50 %. Writes ignored while armed */
#define FPGA_REG_ENC_ERRS        0x28u  /* RO   Illegal quadrature transitions (A and B changed together): [15:0] encoder 1, [31:16] encoder 2. Wraps; CTRL[0] clears */
#define FPGA_REG_SNAP_TICK       0x30u  /* RO   TICK_COUNT of the snapshot (sequence number) */
#define FPGA_REG_SNAP_TIME_US    0x31u  /* RO   TIME_US at the tick */
#define FPGA_REG_SNAP_INPUTS     0x32u  /* RO   SWITCHES at the tick */
#define FPGA_REG_SNAP_SAFETY     0x33u  /* RO   ARM read bits in [3:0], FAULT_STATUS in [11:8], at the tick */
#define FPGA_REG_SNAP_ENC1_COUNT 0x34u  /* RO   Encoder 1 position at the tick: signed 32-bit, 4 counts per encoder line, up when A leads B */
#define FPGA_REG_SNAP_ENC1_DELTA 0x35u  /* RO   Encoder 1 counts since the previous tick (signed) */
#define FPGA_REG_SNAP_ENC2_COUNT 0x36u  /* RO   Encoder 2 position at the tick */
#define FPGA_REG_SNAP_ENC2_DELTA 0x37u  /* RO   Encoder 2 counts since the previous tick */

#define FPGA_ID_VALUE        0x47344650u
#define FPGA_MAP_VERSION     5u
#define FPGA_UNMAPPED_VALUE  0xDEADBEEFu

/* Burst frames: header address 0x7F is the escape, never a register */
#define FPGA_BURST_ADDR      0x7Fu
#define FPGA_BURST_MAX       16u

#define FPGA_ARM_KEY         0x41524D21u
#define FPGA_WDT_TICKS_RESET 3u
#define FPGA_LINK_FAULT_ERRS 4u
#define FPGA_ARM_SWITCH      15u
#define FPGA_SNAP_FAULT_LSB  8u
#define FPGA_DUTY_MAX        32767u
#define FPGA_DUTY_LIMIT_RESET 16384u
#define FPGA_PWM_HZ          20000u
#define FPGA_ENC_FILTER_CLKS 64u

/* LEDS fields */
#define FPGA_LEDS_VALUE      0x00003FFFu

/* SWITCHES fields */
#define FPGA_SW_MASK         0x0000FFFFu
#define FPGA_BTN_U           (1u << 16)
#define FPGA_BTN_L           (1u << 17)
#define FPGA_BTN_R           (1u << 18)
#define FPGA_BTN_D           (1u << 19)
#define FPGA_BTN_C           (1u << 20)

/* SEG7 fields */
#define FPGA_SEG7_HEX        0x0000FFFFu
#define FPGA_SEG7_ALL_DIGITS (0xFu << 16)
#define FPGA_SEG7_USE_REG    (1u << 20)

/* IRQ_STATUS / IRQ_ENABLE fields */
#define FPGA_IRQ_TICK        (1u << 0)
#define FPGA_IRQ_INPUTS      (1u << 1)
#define FPGA_IRQ_CRC_ERR     (1u << 2)
#define FPGA_IRQ_FAULT       (1u << 3)

/* CTRL fields */
#define FPGA_CTRL_CLEAR_COUNTERS (1u << 0)

/* ARM fields */
#define FPGA_ARM_ARMED       (1u << 0)
#define FPGA_ARM_SW_EN       (1u << 1)
#define FPGA_ARM_FAULT       (1u << 2)
#define FPGA_ARM_TICK_ON     (1u << 3)

/* WDT_TICKS fields */
#define FPGA_WDT_TICKS_VALUE 0x000000FFu

/* FAULT_STATUS / FAULT_CLEAR fields */
#define FPGA_FAULT_WDT       (1u << 0)
#define FPGA_FAULT_LINK      (1u << 1)
#define FPGA_FAULT_ESTOP     (1u << 2)
#define FPGA_FAULT_ARM_LOST  (1u << 3)

/* M1_DUTY fields */
#define FPGA_DUTY_MASK       0x0000FFFFu

/* DUTY_LIMIT fields */
#define FPGA_DUTY_LIMIT_VALUE 0x00007FFFu

/* ENC_ERRS fields */
#define FPGA_ENC_ERRS_ENC1   0x0000FFFFu
#define FPGA_ENC_ERRS_ENC2   (0xFFFFu << 16)

/* LOOP_TICK helpers (FPGA system clock is 100 MHz) */
#define FPGA_CLK_HZ          100000000u
#define FPGA_TICK_DIV_FOR_HZ(hz) (FPGA_CLK_HZ / (hz))

#endif /* FPGA_REGS_H */
